-- Phase 66: Geo Management. Geometry stays portable JSONB until PostGIS is validated in each environment.
-- quality: allow-nonconcurrent-index reason=new-empty-phase66-tables
create schema if not exists geo_management_private;
revoke all on schema geo_management_private from public,anon,authenticated;

create table public.geo_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{geo:view}',store_ids uuid[] not null default '{}',brand_ids uuid[] not null default '{}',region_ids uuid[] not null default '{}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.geo_provider_configs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,provider_key text not null,capabilities text[] not null default '{}',secret_reference text,settings jsonb not null default '{}',status text not null default 'inactive' check(status in('active','inactive','degraded')),priority integer not null default 100,monthly_request_limit integer,active boolean not null default false,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,provider_key));
create table public.geo_locations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,entity_type text not null check(entity_type in('store','warehouse','supplier','customer_address','event','custom')),entity_id uuid not null,street text,number text,complement text,neighborhood text,city text,state text,postal_code text,country char(2) not null default 'BR',latitude numeric(10,7),longitude numeric(10,7),normalization_status text not null default 'unverified' check(normalization_status in('valid','partial','ambiguous','invalid','unverified')),geocode_quality text not null default 'unknown' check(geocode_quality in('exact','interpolated','approximate','postal_code','city_level','unknown')),provider text,provider_place_reference text,address_hash text,confirmed_by uuid references auth.users(id),confirmed_at timestamptz,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,entity_type,entity_id),check(latitude is null or latitude between -90 and 90),check(longitude is null or longitude between -180 and 180));
create table public.geo_geocode_cache(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,provider_key text not null,address_hash text not null,normalizer_version integer not null default 1,response_payload jsonb not null default '{}',latitude numeric(10,7),longitude numeric(10,7),geocode_quality text not null default 'unknown',validated boolean not null default false,expires_at timestamptz not null,created_at timestamptz not null default now(),unique(organization_id,provider_key,address_hash,normalizer_version));
create table public.geo_territories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,territory_type text not null check(territory_type in('franchise','delivery','commercial','expansion','operational','marketing','custom')),scope_type text not null check(scope_type in('organization','brand','region','store','custom')),scope_id uuid,geometry_type text not null check(geometry_type in('polygon','multipolygon','radius','postal_code_set','neighborhood_set','city_set')),geometry_data jsonb not null,normalized_bounds jsonb,status text not null default 'draft' check(status in('draft','active','scheduled','archived')),version integer not null default 1,valid_from timestamptz,valid_until timestamptz,parent_territory_id uuid references public.geo_territories(id) on delete set null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(valid_until is null or valid_from is null or valid_until>=valid_from),unique(organization_id,id,version));
create table public.geo_territory_versions(id uuid primary key default gen_random_uuid(),territory_id uuid not null references public.geo_territories(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete cascade,version integer not null,snapshot jsonb not null,change_reason text,changeset_id uuid,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(territory_id,version));
create table public.territory_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,territory_type text not null,overlap_policy text not null default 'review' check(overlap_policy in('allow','review','deny')),exclusivity text not null default 'none' check(exclusivity in('exclusive','shared','preferred','none')),assignment_policy text not null default 'manual_priority' check(assignment_policy in('nearest_store','assigned_territory','load_balanced','customer_choice','manual_priority')),approval_required boolean not null default true,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(organization_id,territory_type));
create table public.service_areas(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,service_type text not null check(service_type in('delivery','pickup','field_service_future','marketing','franchise')),territory_id uuid not null references public.geo_territories(id) on delete restrict,priority integer not null default 100,active boolean not null default true,config jsonb not null default '{}',created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id,service_type,territory_id));
create table public.postal_service_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,service_area_id uuid not null references public.service_areas(id) on delete cascade,country char(2) not null default 'BR',postal_code_pattern text not null,match_type text not null default 'prefix' check(match_type in('exact','prefix','range')),range_end text,priority integer not null default 100,active boolean not null default true,created_at timestamptz not null default now());
create table public.franchise_territory_assignments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,territory_id uuid not null references public.geo_territories(id) on delete restrict,financial_profile_id uuid references public.franchise_financial_profiles(id) on delete restrict,store_id uuid references public.establishments(id) on delete restrict,contract_id uuid references public.contracts(id) on delete restrict,assignment_type text not null default 'preferred' check(assignment_type in('exclusive','shared','preferred')),status text not null default 'draft' check(status in('draft','pending_approval','active','suspended','ended')),valid_from date,valid_until date,approval_id uuid references public.internal_approvals(id) on delete restrict,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(store_id is not null or financial_profile_id is not null),check(valid_until is null or valid_from is null or valid_until>=valid_from));
create table public.store_catchment_areas(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid not null references public.establishments(id) on delete cascade,resolution_type text not null check(resolution_type in('grid','neighborhood','postal_prefix','hex','zone')),resolution_key text not null,period_start date not null,period_end date not null,customer_count integer not null default 0,order_count integer not null default 0,revenue_cents bigint not null default 0,average_delivery_minutes numeric(10,2),complaint_count integer not null default 0,privacy_threshold integer not null default 5,suppressed boolean not null default false,created_at timestamptz not null default now(),unique(store_id,resolution_type,resolution_key,period_start,period_end));
create table public.site_candidates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,opportunity_id uuid references public.expansion_opportunities(id) on delete set null,address_text text,latitude numeric(10,7),longitude numeric(10,7),territory_id uuid references public.geo_territories(id) on delete set null,status text not null default 'draft' check(status in('draft','review','shortlisted','approved','rejected','archived')),score_components jsonb not null default '{}',notes text,decision_by uuid references auth.users(id),decision_at timestamptz,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.geo_changesets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,change_type text not null check(change_type in('territory_create','boundary_change','assignment_change','service_area_change')),status text not null default 'draft' check(status in('draft','review','approved','published','rolled_back')),preview jsonb,approval_id uuid references public.internal_approvals(id) on delete restrict,published_by uuid references auth.users(id),published_at timestamptz,rolled_back_by uuid references auth.users(id),rolled_back_at timestamptz,rollback_reason text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.geo_territory_versions add constraint geo_territory_versions_changeset_fk foreign key(changeset_id) references public.geo_changesets(id) on delete set null;
create table public.geo_changeset_items(id uuid primary key default gen_random_uuid(),changeset_id uuid not null references public.geo_changesets(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,entity_type text not null,entity_id uuid,before_state jsonb,after_state jsonb not null,validation_results jsonb not null default '{}',created_at timestamptz not null default now());
create table public.geo_audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,actor_user_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,correlation_id uuid,created_at timestamptz not null default now());
create table public.geo_provider_usage(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,provider_key text not null,operation text not null,status text not null,latency_ms integer,cache_hit boolean not null default false,cost_units numeric(12,4) not null default 0,occurred_at timestamptz not null default now());

alter table public.delivery_zones add column if not exists territory_id uuid references public.geo_territories(id) on delete set null;
alter table public.network_regions add column if not exists territory_id uuid references public.geo_territories(id) on delete set null;
alter table public.expansion_opportunities add column if not exists geo_territory_id uuid references public.geo_territories(id) on delete set null;

create table public.fact_geo_serviceability(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,service_area_id uuid,result text not null,resolution_method text,occurred_at timestamptz not null,loaded_at timestamptz not null default now());
create table public.fact_geo_order_density(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,resolution_type text not null,resolution_key text not null,period_start date not null,order_count integer not null,revenue_cents bigint not null,customer_count integer not null,suppressed boolean not null default false,loaded_at timestamptz not null default now());
create table public.fact_geo_delivery_performance(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,service_area_id uuid,period_start date not null,delivery_count integer not null,average_minutes numeric(10,2),complaint_count integer not null default 0,loaded_at timestamptz not null default now());
create table public.fact_geo_territory_changes(id uuid primary key default gen_random_uuid(),organization_id uuid not null,territory_id uuid,changeset_id uuid,change_type text not null,published_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_geo_overlap_analysis(id uuid primary key default gen_random_uuid(),organization_id uuid not null,territory_a_id uuid,territory_b_id uuid,severity text not null,allowed boolean not null,estimated boolean not null default true,analyzed_at timestamptz not null default now());
create table public.dim_geo_territory(territory_id uuid primary key,organization_id uuid not null,name text not null,territory_type text not null,status text not null,version integer not null,loaded_at timestamptz not null default now());
create table public.dim_geo_service_area(service_area_id uuid primary key,organization_id uuid not null,store_id uuid not null,service_type text not null,active boolean not null,loaded_at timestamptz not null default now());
create table public.dim_geo_region(region_key text primary key,organization_id uuid not null,region_type text not null,label text not null,loaded_at timestamptz not null default now());
create table public.dim_geo_resolution_quality(quality text primary key,label text not null,rank integer not null);
insert into public.dim_geo_resolution_quality values('exact','Exata',1),('interpolated','Interpolada',2),('approximate','Aproximada',3),('postal_code','CEP',4),('city_level','Cidade',5),('unknown','Desconhecida',6) on conflict(quality)do update set label=excluded.label,rank=excluded.rank;

create index geo_locations_scope_idx on public.geo_locations(organization_id,entity_type,entity_id);
create index geo_locations_city_idx on public.geo_locations(organization_id,country,state,city,postal_code);
create index geo_territories_scope_idx on public.geo_territories(organization_id,territory_type,scope_type,scope_id,status);
create index service_areas_store_idx on public.service_areas(organization_id,store_id,service_type,active,priority);
create index postal_service_rules_idx on public.postal_service_rules(organization_id,country,postal_code_pattern,active,priority);
create index geo_changesets_scope_idx on public.geo_changesets(organization_id,status,updated_at desc);
create index geo_audit_scope_idx on public.geo_audit_events(organization_id,entity_type,entity_id,created_at desc);
create index geo_provider_usage_idx on public.geo_provider_usage(organization_id,provider_key,occurred_at desc);

create or replace function geo_management_private.can_access(target_org uuid,requested_permission text default 'geo:view')returns boolean language sql stable security definer set search_path='' as $$select(select auth.uid())is not null and(exists(select 1 from public.organization_members om where om.organization_id=target_org and om.user_id=(select auth.uid())and om.active and om.role in('owner','admin'))or exists(select 1 from public.geo_member_permissions p where p.organization_id=target_org and p.user_id=(select auth.uid())and p.active and(requested_permission=any(p.permissions)or'geo:view_network'=any(p.permissions))));$$;
revoke all on function geo_management_private.can_access(uuid,text)from public,anon;grant execute on function geo_management_private.can_access(uuid,text)to authenticated;

do $$declare t text;begin foreach t in array array['geo_member_permissions','geo_provider_configs','geo_locations','geo_geocode_cache','geo_territories','geo_territory_versions','territory_policies','service_areas','postal_service_rules','franchise_territory_assignments','store_catchment_areas','site_candidates','geo_changesets','geo_changeset_items','geo_audit_events','geo_provider_usage','fact_geo_serviceability','fact_geo_order_density','fact_geo_delivery_performance','fact_geo_territory_changes','fact_geo_overlap_analysis','dim_geo_territory','dim_geo_service_area','dim_geo_region','dim_geo_resolution_quality']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)','geo_service_'||t,t);end loop;end$$;

create or replace function public.publish_geo_changeset(requested_changeset_id uuid,requested_actor uuid)returns public.geo_changesets language plpgsql security definer set search_path='' as $$declare c public.geo_changesets;item public.geo_changeset_items;result public.geo_changesets;begin select * into c from public.geo_changesets where id=requested_changeset_id for update;if not found then raise exception 'changeset not found';end if;if c.status<>'approved'or c.preview is null then raise exception 'approved preview required';end if;if not exists(select 1 from public.internal_approvals a where a.id=c.approval_id and a.status='approved'and a.resolved_at is not null)then raise exception 'approved ActionEngine approval required';end if;for item in select * from public.geo_changeset_items where changeset_id=c.id loop if item.entity_type='territory'then update public.geo_territories set geometry_data=item.after_state->'geometry_data',normalized_bounds=item.after_state->'normalized_bounds',status=coalesce(item.after_state->>'status','active'),version=version+1,updated_at=now()where id=item.entity_id and organization_id=c.organization_id;insert into public.geo_territory_versions(territory_id,organization_id,version,snapshot,change_reason,changeset_id,created_by)select g.id,g.organization_id,g.version,to_jsonb(g),'Changeset publicado',c.id,requested_actor from public.geo_territories g where g.id=item.entity_id;end if;end loop;update public.geo_changesets set status='published',published_by=requested_actor,published_at=now(),updated_at=now()where id=c.id returning * into result;return result;end$$;
revoke all on function public.publish_geo_changeset(uuid,uuid)from public,anon,authenticated;grant execute on function public.publish_geo_changeset(uuid,uuid)to service_role;
create or replace function public.rollback_geo_changeset(requested_changeset_id uuid,requested_actor uuid,requested_reason text)returns public.geo_changesets language plpgsql security definer set search_path='' as $$declare c public.geo_changesets;item public.geo_changeset_items;result public.geo_changesets;begin if coalesce(btrim(requested_reason),'')=''then raise exception 'rollback reason required';end if;select * into c from public.geo_changesets where id=requested_changeset_id and status='published'for update;if not found then raise exception 'published changeset not found';end if;for item in select * from public.geo_changeset_items where changeset_id=c.id loop if item.entity_type='territory'and item.before_state is not null then update public.geo_territories set geometry_data=item.before_state->'geometry_data',normalized_bounds=item.before_state->'normalized_bounds',status=coalesce(item.before_state->>'status','active'),version=version+1,updated_at=now()where id=item.entity_id and organization_id=c.organization_id;insert into public.geo_territory_versions(territory_id,organization_id,version,snapshot,change_reason,changeset_id,created_by)select g.id,g.organization_id,g.version,to_jsonb(g),requested_reason,c.id,requested_actor from public.geo_territories g where g.id=item.entity_id;end if;end loop;update public.geo_changesets set status='rolled_back',rolled_back_by=requested_actor,rolled_back_at=now(),rollback_reason=requested_reason,updated_at=now()where id=c.id returning * into result;return result;end$$;
revoke all on function public.rollback_geo_changeset(uuid,uuid,text)from public,anon,authenticated;grant execute on function public.rollback_geo_changeset(uuid,uuid,text)to service_role;

