insert into public.report_templates(name,description,category,dataset_id,definition_json,system_template,read_only,required_permissions,widget_compatible)values('Cobertura por Unidade','Áreas e serviços ativos por unidade.','geo','geo_service_areas','{"type":"grouped_table","groupBy":["store","service_type"]}',true,true,'{reports:view,geo:view}',true),('Lacunas de Entrega','Demanda agregada fora da cobertura.','geo','geo_delivery_coverage','{"type":"map_summary","privacyThreshold":5}',true,true,'{reports:view,geo:view_analytics}',true),('Performance de Delivery por Área','Tempo e reclamações por área agregada.','geo','geo_delivery_coverage','{"type":"trend","metrics":["geo_average_delivery_minutes"]}',true,true,'{reports:view,geo:view_analytics}',true),('Densidade de Pedidos','Pedidos e receita por resolução agregada.','geo','geo_order_density','{"type":"density","privacyThreshold":5,"individualPoints":false}',true,true,'{reports:view,geo:view_analytics}',true),('Conflitos Territoriais','Sobreposições e exclusividade pendentes.','geo','geo_territories','{"type":"table","filter":{"overlap":true}}',true,true,'{reports:view,geo:manage_territories}',false),('Qualidade de Geocodificação','Qualidade e pendências das localizações.','geo','geo_store_locations','{"type":"grouped_table","groupBy":["geocode_quality"]}',true,true,'{reports:view,geo:view_store_locations}',true),('Territórios de Franquia','Atribuições territoriais de franquia.','geo','geo_territories','{"type":"table","filter":{"territory_type":"franchise"}}',true,true,'{reports:view,geo:manage_franchise_territories}',false),('Expansão Geográfica','Candidatos e componentes geográficos estimados.','geo','geo_expansion_analysis','{"type":"table","disclaimer":"Estimativa geográfica — não é garantia financeira."}',true,true,'{reports:view,geo:simulate_expansion}',false)on conflict do nothing;
